async function api(path,method='GET',body,raw=false) {
  const url = new URL('/api/'+path,location.origin);
  if(state.customer) url.searchParams.set('customer_id',state.customer.id);
  const r = await fetch(url,{method,headers:method==='GET'?{}:{'Content-Type':'application/json','X-Requested-With':'PokerBackoffice'},body:body===undefined?undefined:JSON.stringify(body)});
  if(r.status===401) throw new Error('Sign in with Microsoft to continue');
  if(!r.ok) {const v=await r.json().catch(()=>({}));throw new Error(v.error || `Request failed (${r.status})`);}
  return raw ? r.blob() : r.json();
}
